export interface LeadCapture {
  leadCaptureId: number;
  companyId: number; // For internal users, this field exists in the DB
  fullName: string;
  email: string;
  companyName?: string;
  phone?: string;
  jobTitle?: string;
  message?: string;
  leadSource: string;
  interestArea?: string;
  status: string;
  assignedTo?: number;
  privacyConsentAccepted: boolean;
  created_At: string;
  updated_at?: string;
}

export interface LeadCaptureListResponse {
  leadCaptures: LeadCapture[];
}

// Payload for public unauthenticated creation
export type CreateLeadCapturePayload = Omit<
  LeadCapture,
  "leadCaptureId" | "companyId" | "created_At" | "updated_at" | "status" | "assignedTo"
>;

// GET ALL — POST /all_leadCaptures
export async function getAllLeadCaptures(companyId: number): Promise<LeadCapture[]> {
  const res = await fetch(BASE_URL + "/all_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures ?? [];
}

// GET ONE — POST /one_leadCaptures
export async function getOneLeadCapture(leadCaptureId: number, companyId: number): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/one_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "leadCaptureId": leadCaptureId, "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data = await res.json();
  // The API returns an array, so we need to unwrap it.
  return data.leadCaptures[0];
}

// CREATE — action: 1 (public endpoint)
export async function createLeadCapture(payload: CreateLeadCapturePayload): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 1, ...payload }] }),
  });
  // Per ADR-002: Backend now returns 400 on duplicate. `res.ok` handles this.
  if (!res.ok) {
    const errorData = await res.json();
    throw new Error(errorData.error || 'Error creating lead capture');
  }
  return await res.json();
}

// UPDATE — action: 2
export async function updateLeadCapture(id: number, companyId: number, payload: Partial<LeadCapture>): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 2, "leadCaptureId": id, "companyId": companyId, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// DELETE — action: 3
export async function deleteLeadCapture(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 3, "leadCaptureId": id, "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}
