                  labelPlacement="floating"
                  value={newLeadForm.leadSource}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setNewLeadForm(p => ({ ...p, leadSource: e.detail.value! }))}
                  className={!newLeadForm.leadSource ? 'ion-invalid ion-touched' : ''}
                  errorText={!newLeadForm.leadSource ? 'Origen del lead es obligatorio' : ''}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Área de Interés"
                  labelPlacement="floating"
                  value={newLeadForm.interestArea}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setNewLeadForm(p => ({ ...p, interestArea: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Mensaje"
                  labelPlacement="floating"
                  value={newLeadForm.message}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setNewLeadForm(p => ({ ...p, message: e.detail.value! }))}
                />
              </div>
              <div className="wizard-field-group">
                <IonItem lines="none" className="privacy-consent-item">
                  <IonLabel className="ion-text-wrap">Acepto la política de privacidad *</IonLabel>
                  <IonInput
                    type="checkbox"
                    checked={newLeadForm.privacyConsentAccepted}
                    onIonChange={(e: CustomEvent<InputInputEventDetail>) => setNewLeadForm(p => ({ ...p, privacyConsentAccepted: e.detail.checked! }))}
                    slot="end"
                  />
                </IonItem>
                {!newLeadForm.privacyConsentAccepted && (
                  <p className="ion-padding-start ion-text-danger" style={{ fontSize: '12px', marginTop: '-10px' }}>
                    Debe aceptar la política de privacidad.
                  </p>
                )}
              </div>
              <IonButton expand="block" onClick={handleCreateLead} disabled={creating || !newLeadForm.fullName || !newLeadForm.email || !newLeadForm.leadSource || !newLeadForm.privacyConsentAccepted || (!newLeadForm.email.includes('@') && newLeadForm.email.length > 0)}>
                {creating ? <IonSpinner name="dots" /> : 'Crear Lead'}
              </IonButton>
            </div>
          </IonContent>
        </IonModal>

        {/* Edit Lead Modal */}
        <IonModal isOpen={showEditModal} onDidDismiss={() => setShowEditModal(false)}>
          <IonHeader>
            <IonToolbar>
              <IonTitle>Editar Lead</IonTitle>
              <IonButton slot="end" fill="clear" onClick={() => setShowEditModal(false)}>
                <IonIcon icon={close} />
              </IonButton>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            {selectedLead && (
              <div className="lead-capture-form">
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Nombre Completo"
                    labelPlacement="floating"
                    value={editLeadForm.fullName}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditLeadForm(p => ({ ...p, fullName: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Email"
                    labelPlacement="floating"
                    type="email"
                    value={editLeadForm.email}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditLeadForm(p => ({ ...p, email: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Empresa"
                    labelPlacement="floating"
                    value={editLeadForm.companyName}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditLeadForm(p => ({ ...p, companyName: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Teléfono"
                    labelPlacement="floating"
                    type="tel"
                    value={editLeadForm.phone}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditLeadForm(p => ({ ...p, phone: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Puesto"
                    labelPlacement="floating"
                    value={editLeadForm.jobTitle}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditLeadForm(p => ({ ...p, jobTitle: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Origen del Lead"
                    labelPlacement="floating"
                    value={editLeadForm.leadSource}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditLeadForm(p => ({ ...p, leadSource: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Área de Interés"
                    labelPlacement="floating"
                    value={editLeadForm.interestArea}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditLeadForm(p => ({ ...p, interestArea: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Mensaje"
                    labelPlacement="floating"
                    value={editLeadForm.message}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setEditLeadForm(p => ({ ...p, message: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonItem lines="none" className="privacy-consent-item">
                    <IonLabel className="ion-text-wrap">Acepto la política de privacidad</IonLabel>
                    <IonInput
                      type="checkbox"
                      checked={editLeadForm.privacyConsentAccepted}
                      onIonChange={(e: CustomEvent<InputInputEventDetail>) => setEditLeadForm(p => ({ ...p, privacyConsentAccepted: e.detail.checked! }))}
                      slot="end"
                    />
                  </IonItem>
                </div>
                <IonButton expand="block" onClick={handleUpdateLead} disabled={updating}>
                  {updating ? <IonSpinner name="dots" /> : 'Guardar Cambios'}
                </IonButton>
              </div>
            )}
          </IonContent>
        </IonModal>

        {/* Delete Lead Alert */}
        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={`¿Estás seguro de que quieres eliminar el lead de "${selectedLead?.fullName}"?`}
          buttons=[
            {
              text: 'Cancelar',
              role: 'cancel',
              cssClass: 'delete-alert-cancel',
            },
            {
              text: 'Eliminar',
              cssClass: 'delete-alert-confirm',
              handler: () => {
                handleDeleteLead();
              },
            },
          ]
        />

        <IonToast
          isOpen={showToast}
          message={toastMessage}
          duration={3000}
          onDidDismiss={() => setShowToast(false)}
          color={error ? 'danger' : 'success'}
        />
      </IonContent>
    </IonPage>
  );
};

export default LeadCapturePage;
